	raw, err := s.herdrCall(ctx, "pane.read", map[string]any{"pane_id": paneID, "source": "visible"})
	if err != nil {
		return ""
	}
	var screen struct {
		Read struct {
			Text string `json:"text"`
		} `json:"read"`
	}
	if json.Unmarshal(raw, &screen) != nil {
		return ""
	}
	return screen.Read.Text
}

func (s *Service) codexUpdatePrompt(ctx context.Context, paneID string) bool {
	snapshot, err := s.snapshot(ctx)
	if err != nil {
		return false
	}
	pane, found := findAppPane(snapshot.Panes, paneID, "")
	if !found || pane.Agent != "codex" {
		return false
	}
	screen := strings.ToLower(s.visibleScreen(ctx, paneID))
	return strings.Contains(screen, "codex is available") &&
		(strings.Contains(screen, "update") || strings.Contains(screen, "upgrade"))
}

func isAgentBlocked(err error) bool {
	var failure *axi.Error
	return errors.As(err, &failure) && failure.Code == "agent_blocked"
}

func isPromptStall(err error) bool {
	var failure *axi.Error
	return errors.As(err, &failure) && (failure.Code == "agent_prompt_stalled" || failure.Code == "timeout")
}

func (s *Service) agentActive(ctx context.Context, paneID string) bool {
	raw, err := s.herdrCall(ctx, "agent.get", map[string]any{"target": paneID})
	if err != nil {
		return false
	}
	var response struct {
		Agent struct {
			AgentStatus string `json:"agent_status"`
		} `json:"agent"`
	}
	if json.Unmarshal(raw, &response) != nil {
		return false
	}
	return response.Agent.AgentStatus == "working" || response.Agent.AgentStatus == "blocked"
}

func findAppPane(panes []herdr.Pane, paneID, label string) (herdr.Pane, bool) {
	return herdr.FindPane(panes, paneID, label)
}

var (
	agentStopGrace = 5 * time.Second
	agentKillGrace = 2 * time.Second
)

// stopPaneAgent ends the agent in the pane and waits until the pane's shell is
// back in the foreground. Herdr may retain lifecycle authority after the
// process exits, so the final clear uses the stopped authority's source and
// sequence when Herdr exposes that session identity. The extra shell check
// also closes the common interleaving in which a User starts a replacement
// while the stop operation is in flight.
func (s *Service) stopPaneAgent(ctx context.Context, paneID string, expectedAgent ...string) error {
	kind := ""
	if len(expectedAgent) > 0 {
		kind = expectedAgent[0]
	}
	group, err := s.paneAgentGroup(ctx, paneID)
	if err != nil {
		return err
	}
	if group == 0 {
		if kind != "" || s.paneHasAgentAuthority(ctx, paneID) {
			current, err := s.paneAgentGroup(ctx, paneID)
			if err != nil {
				return err
			}
			if current != 0 {
				return agentStopPaneChanged(paneID)
			}
		}
		return s.clearStoppedPaneAgentAuthority(ctx, paneID, kind)
	}

