package app

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"sort"
	"strings"
	"syscall"
	"time"

	"github.com/thanhbinh1905/posse/internal/axi"
	"github.com/thanhbinh1905/posse/internal/herdr"
)

func (s *Service) herdrCall(ctx context.Context, method string, params map[string]any) (json.RawMessage, error) {
	if s.Herdr == nil {
		return nil, axi.Failure("herdr_unavailable", "Herdr adapter is not configured", true, "Run `posse doctor` to inspect setup")
	}
	result, err := s.Herdr.Call(ctx, method, params)
	if err != nil {
		return nil, fmt.Errorf("call Herdr method %s: %w", method, herdrError(err))
	}
	return result, nil
}

func (s *Service) snapshot(ctx context.Context) (herdr.Snapshot, error) {
	if s.Herdr == nil {
		return herdr.Snapshot{}, axi.Failure("herdr_unavailable", "Herdr adapter is not configured", true)
	}
	if err := s.Herdr.CheckProtocol(ctx); err != nil {
		return herdr.Snapshot{}, herdrError(err)
	}
	snapshot, err := s.Herdr.Snapshot(ctx)
	if err != nil {
		return herdr.Snapshot{}, fmt.Errorf("call Herdr method session.snapshot: %w", herdrError(err))
	}
	return snapshot, nil
}

func (s *Service) safePrompt(ctx context.Context, paneID, text string) error {
	return s.safePromptWhen(ctx, paneID, text, nil)
}

func (s *Service) safePromptWhen(ctx context.Context, paneID, text string, allowed func(herdr.Snapshot) error) error {
	return s.prompt(ctx, paneID, map[string]any{"target": paneID, "text": text}, allowed)
}

func (s *Service) safePromptWhenWithSubmissionGate(ctx context.Context, paneID, text string, allowed func(herdr.Snapshot) error, gate func(func() error) error) error {
	return s.typeIntoBeforeWithSubmissionGate(ctx, paneID, "agent.prompt", map[string]any{"target": paneID, "text": text}, allowed, nil, gate, false)
}

func (s *Service) prompt(ctx context.Context, paneID string, params map[string]any, allowed func(herdr.Snapshot) error) error {
	return s.promptBefore(ctx, paneID, params, allowed, nil)
}

func (s *Service) promptBefore(ctx context.Context, paneID string, params map[string]any, allowed func(herdr.Snapshot) error, beforePrompt func() error) error {
	return s.typeIntoBefore(ctx, paneID, "agent.prompt", params, allowed, beforePrompt)
}

// typeInto sends input unless the pane is focused or the agent waits at a dialog.
func (s *Service) typeInto(ctx context.Context, paneID, method string, params map[string]any, allowed func(herdr.Snapshot) error) error {
	return s.typeIntoBefore(ctx, paneID, method, params, allowed, nil)
}

func (s *Service) typeIntoFocused(ctx context.Context, paneID, method string, params map[string]any, allowed func(herdr.Snapshot) error) error {
	return s.typeIntoBeforeWithSubmissionGate(ctx, paneID, method, params, allowed, nil, nil, true)
}

func (s *Service) typeIntoBefore(ctx context.Context, paneID, method string, params map[string]any, allowed func(herdr.Snapshot) error, beforeSend func() error) error {
	return s.typeIntoBeforeWithSubmissionGate(ctx, paneID, method, params, allowed, beforeSend, nil, false)
}

func (s *Service) typeIntoBeforeWithSubmissionGate(ctx context.Context, paneID, method string, params map[string]any, allowed func(herdr.Snapshot) error, beforeSend func() error, gate func(func() error) error, allowFocused bool) error {
	snapshot, err := s.snapshot(ctx)
	if err != nil {
		return err
	}
	for _, pane := range snapshot.Panes {
		if pane.PaneID != paneID {
			continue
		}
		if !allowFocused && (pane.Focused || snapshot.FocusedPaneID == paneID) {
			return axi.Failure("pane_focused", "refusing to type into a focused pane", false, "Unfocus the pane, then retry")
		}
		if pane.AgentStatus == "blocked" {
			return axi.Failure("agent_blocked", "refusing to type into a blocked agent", false, "Inspect the Worker dialog before retrying")
		}
	}
	if allowed != nil {
		if err := allowed(snapshot); err != nil {
			return err
		}
	}
	if beforeSend != nil {
		if err := beforeSend(); err != nil {
			return err
		}
	}
	submit := func() error {
		if method == "agent.prompt" {
			crashIntentAt("send", "before", "message.prompt")
		}
		_, err := s.herdrCall(ctx, method, params)
		return err
	}
	if gate != nil {
		return gate(submit)
	}
	return submit()
}

var (
	agentStartBusyWait   = 10 * time.Second
	agentStartRetryDelay = 250 * time.Millisecond
)

// ttyLineMaxBytes is the longest line a tty in canonical mode accepts, as in a
// /bin/sh pane. The kernel discards a longer line without an error.
const ttyLineMaxBytes = 4095

var nonPOSIXShells = map[string]bool{"fish": true, "csh": true, "tcsh": true, "nu": true, "elvish": true, "xonsh": true, "pwsh": true}

// paneShellName names the pane's shell while it is the foreground process, or
// returns "" when Herdr cannot tell.
func (s *Service) paneShellName(ctx context.Context, paneID string) string {
	info, err := s.sandboxPaneProcessInfo(ctx, paneID)
	if err != nil {
		return ""
	}
	for _, process := range info.ForegroundProcesses {
		if process.PID == info.ShellPID {
			return process.Name
		}
	}
	return ""
}

var shellFunctionName = regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_]*$`)

// launchAgent exports env into a pane's shell and starts an agent there. Each
// is typed as one shell line, so when a line would pass the tty limit the
// exports and a shell function named after the agent's command, holding its
// arguments, are written to script. The pane sources script, and Herdr then
// types the bare command, which runs the function once.
func (s *Service) launchAgent(ctx context.Context, paneID, name, kind string, args []string, env map[string]string, script string) error {
	if kind == "codex" {
		updateCheck := []string{"-c", "check_for_update_on_startup=false"}
		insertAt := len(args)
		for index, arg := range args {
			if arg == "resume" {
				insertAt = index
				break
			}
		}
		if insertAt == len(args) && insertAt > 0 && args[insertAt-1] == codexOpeningPrompt {
			insertAt--
		}
		args = append(args[:insertAt], append(updateCheck, args[insertAt:]...)...)
	}
	command := agentCLIName(kind)
	keys := make([]string, 0, len(env))
	for key := range env {
		keys = append(keys, key)
	}
	sort.Strings(keys)
	lines := make([]string, 0, len(keys))
	for _, key := range keys {
		lines = append(lines, "export "+key+"="+shellQuote(env[key]))
	}
	launch := command
	for _, argument := range args {
		launch += " " + shellQuote(argument)
	}
	longest := len(launch)
	for _, line := range lines {
		longest = max(longest, len(line))
	}
	if longest > ttyLineMaxBytes {
		if !shellFunctionName.MatchString(command) {
			return axi.Failure("launch_line_too_long", fmt.Sprintf("the %s launch needs a %d-byte shell line, over the %d-byte tty line limit, and %s cannot be a shell function name", kind, longest, ttyLineMaxBytes, command), false, "Shorten the Profile arguments or launch environment")
		}
		if shell := s.paneShellName(ctx, paneID); nonPOSIXShells[shell] {
			return axi.Failure("launch_shell_unsupported", fmt.Sprintf("the %s launch needs a %d-byte shell line, over the %d-byte tty line limit, and the pane shell %s cannot source the POSIX launch script", kind, longest, ttyLineMaxBytes, shell), false, "Use a POSIX pane shell such as sh, bash or zsh, or shorten the Profile arguments or launch environment")
		}
		contents := strings.Join(append(lines, command+"() {", "\tunset -f "+command, "\tcommand "+launch+` "$@"`, "}"), "\n") + "\n"
		if err := writeFile(script, []byte(contents)); err != nil {
			return err
		}
		lines, args = []string{". " + shellQuote(script)}, []string{}
	}
	for _, line := range lines {
		if err := s.sendLaunchInput(ctx, paneID, line); err != nil {
			return err
		}
	}
	_, err := s.startAgent(ctx, map[string]any{"name": name, "kind": kind, "pane_id": paneID, "args": args})
	return err
}

// startAgent starts an agent in a pane that may have just opened. Herdr queues
// a launch before the pane's shell starts, but rejects it with agent_pane_busy
// while the shell is still running its startup commands, so the start is
// retried until the shell reaches its prompt. Exhausting that bound reports a
// retryable busy error so a later relaunch can try again after Herdr catches up.
func (s *Service) sendLaunchInput(ctx context.Context, paneID, text string) error {
	_, err := retryAgentPaneBusy(ctx, func() (json.RawMessage, error) {
		return s.herdrCall(ctx, "pane.send_input", map[string]any{"pane_id": paneID, "text": text, "keys": []string{"enter"}})
	})
	return err
}

func (s *Service) startAgent(ctx context.Context, params map[string]any) (json.RawMessage, error) {
	return retryAgentPaneBusy(ctx, func() (json.RawMessage, error) {
		return s.herdrCall(ctx, "agent.start", params)
	})
}

func retryAgentPaneBusy(ctx context.Context, attempt func() (json.RawMessage, error)) (json.RawMessage, error) {
	deadline := time.Now().Add(agentStartBusyWait)
	for {
		result, err := attempt()
		var failure *axi.Error
		if err == nil || !errors.As(err, &failure) || failure.Code != "agent_pane_busy" {
			return result, err
		}
		if time.Now().After(deadline) {
			return nil, axi.Failure("agent_pane_busy", failure.Message, true, "Wait for the Worker pane's shell to become available, then retry")
		}
		select {
		case <-ctx.Done():
			return nil, ctx.Err()
		case <-time.After(agentStartRetryDelay):
		}
	}
}

const (
	launchPromptAttempts     = 4
	launchPromptActivityWait = 10 * time.Second
)

var launchPromptRetryDelay = time.Second

// deliverLaunchPrompt submits the first prompt to a freshly started agent and
// confirms that the agent started working on it. An agent TUI can report
// interactive readiness before it reads input, and Codex then silently drops
// the submission, so the prompt is resent until Herdr observes activity.
func (s *Service) deliverLaunchPrompt(ctx context.Context, paneID, text string) error {
	return s.confirmPrompt(ctx, paneID, text, func(ctx context.Context, method string, params map[string]any) error {
		return s.typeInto(ctx, paneID, method, params, nil)
	})
}

func (s *Service) deliverLaunchPromptFocused(ctx context.Context, paneID, text string) error {
	return s.confirmPrompt(ctx, paneID, text, func(ctx context.Context, method string, params map[string]any) error {
		return s.typeIntoFocused(ctx, paneID, method, params, nil)
	})
}

// deliverLeadPrompt is deliverLaunchPrompt for a Lead started in the pane that
// ran `posse up`. That pane is focused by design, so the focused-pane guard
// that protects Worker panes from typing over the User does not apply.
func (s *Service) deliverLeadPrompt(ctx context.Context, paneID, text string) error {
	return s.confirmPrompt(ctx, paneID, text, func(ctx context.Context, method string, params map[string]any) error {
		_, err := s.herdrCall(ctx, method, params)
		return err
	})
}

// confirmPrompt types text into the agent and submits it until Herdr observes
// the agent working. When a submission stalls with the text still on screen,
// only its Enter was lost, as with Pi, so Enter is pressed instead of retyping
// the text next to the unsubmitted copy.
func (s *Service) confirmPrompt(ctx context.Context, paneID, text string, send func(ctx context.Context, method string, params map[string]any) error) error {
	activity := map[string]any{"until": []string{"working", "blocked"}, "timeout_ms": launchPromptActivityWait.Milliseconds()}
	var lastErr error
	pressedEnter := false
	for attempt := 1; attempt <= launchPromptAttempts; attempt++ {
