package app

import (
	"context"
	"embed"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/thanhbinh1905/posse/internal/axi"
	"github.com/thanhbinh1905/posse/internal/config"
	"github.com/thanhbinh1905/posse/internal/execgroup"
	"github.com/thanhbinh1905/posse/internal/store"
)

//go:embed lead_pi_extension.ts
var leadPiExtension string

//go:embed lead_opencode_plugin.js
var leadOpenCodePlugin string

//go:embed claude_lowkey/.claude-plugin/plugin.json claude_lowkey/FIRSTMATE-LICENSE claude_lowkey/hooks claude_lowkey/lib
var leadClaudeLowkey embed.FS

// The prompt limit is a byte-based approximation, not a model tokenizer.
const (
	leadInstructionTokenBudget   = 7500
	leadInstructionBytesPerToken = 4
	leadInstructionMaxBytes      = leadInstructionTokenBudget * leadInstructionBytesPerToken
	codexQueueTimeout            = 5 * time.Second
)

// codexOpeningPrompt starts the first turn of a codex Lead so codex creates the
// session that `codex queue` needs. It is passed as codex's own start prompt, so
// nothing is typed into the pane.
const codexOpeningPrompt = "Run `posse` and give the User a short status of the Project."

// noPollRule forbids spending turns on waiting; each polling turn resends the
// Lead's whole context.
const noPollRule = "Never poll with sleep, `posse peek`, `posse list` or repeated `posse` calls to wait for Workers, CI or PRs; use `posse peek` only to inspect a specific concern."

const lowkeyReportingRule = "Lowkey mode on: message the User only about needs-decision, message/notice_delivery_uncertain, lead_receiver_missing, merge_ready when autonomy.merge=ask, failed/lost, quota_exhausted, budget_exceeded, pr_closed, pr_merged_ungated, review_policy_violation, head_discontinuity, persistent pr_watch_failing/root_fetch_failing, and completed outcomes (done after review, pr_merged). Acknowledge routine Notices (pr_opened, quota_fallback, working notes, pr_watch_recovered, root_fetch_recovered, first pr_watch_failing, restarts) silently; group only if useful. Never answer a needs-decision Notice for the User. The wake includes the Notice text; don't run `posse` just to learn what arrived. Inspect with `posse show <task>` when needed."

const normalReportingRule = "Lowkey mode off: handle every Notice, tell the User the outcome in your own words without waiting to be asked, then run `posse ack <id|all>`. Posse runs configured `notify.command` with JSON User-actionable Notices on stdin."

func reportingRule(lowkey bool) string {
	if lowkey {
		return lowkeyReportingRule + " Posse runs configured `notify.command` with JSON User-actionable Notices on stdin."
	}
	return normalReportingRule
}

// noticeRule tells the Lead how its Notices arrive for the given delivery mode
// and how to wait for them.
func noticeRule(delivery, kind string) string {
	switch delivery {
	case config.NoticeDeliveryWatch:
		if kind != "claude" {
			return "Keep exactly one `posse watch` running as a background command that re-invokes you when it returns. Handle Notices, acknowledge handled IDs with `posse ack <ids>`, then restart the background watch. " + noPollRule + " After (re)starting it, end your turn and let it wake you."
		}
		return "Keep exactly one `posse watch --json --quiet-routine --handoff --destination \"claude:$CLAUDE_CODE_SESSION_ID\"` running as a background command without a timeout. In Claude Code's local interactive session, the background Bash command waits without model turns. When Claude Code reports that the command completed, use `Read` on the output file it names to get the JSON Notice batch. Handle only that returned batch, acknowledge its exact Notice IDs with `posse ack <ids>` so its receipt is accepted, then start a replacement Watch only if `posse watch --status --destination \"claude:$CLAUDE_CODE_SESSION_ID\"` reports `inactive`. If a Watch you start prints `\"state\":\"already_active\"`, another Watch for this session is still waiting with the named pid; that result holds no Notices, so start nothing more. Do not retry an uncertain receipt blindly. Read the current lowkey state and reporting rule in each Notice. " + noPollRule + " After starting the waiter, end your turn and let it wake you."
	case config.NoticeDeliveryCodexQueue:
		return "posse queues each batch of Notices into this conversation as a Posse Notice message, also while your pane is focused or the User is typing. Read the current lowkey state and reporting rule in each message. Do not run `posse watch`. " + noPollRule + " End your turn and let that message wake you."
	case config.NoticeDeliveryPiExtension:
		return "The Pi extension delivers Notices through Pi's persisted session queue, using a durable Posse receipt keyed by a stable batch ID. A queued follow-up is not accepted until `agent_settled` confirms its Notice metadata, exact IDs, and delivery or batch ID in persisted session entries; a warning quoting an ID is not acceptance. It checks the session before injection and does not repeat an accepted batch. If the persisted receipt is missing or unsupported at settlement, inspect the named session and do not retry blindly; a replacement session may reconcile a matching current-session batch record, otherwise ask the User if the outcome cannot be established. The old batch stays held while fresh independent Notices continue. If delivery pauses, repair the reported failure and use `/posse-notices retry`; that command never resolves held receipts. Actionable Notices arrive as hidden Posse Notice messages when lowkey is on, even while the User is typing or you are working. It acknowledges pr_opened without a turn only when lowkey is on; handle and acknowledge all other Notices yourself. With lowkey off, every Notice arrives as a visible Posse Notice message and needs full reporting. Read the current lowkey state and reporting rule in each message. Do not run `posse watch`. " + noPollRule + " End your turn and let that message wake you."
	case config.NoticeDeliveryOpenCodePlugin:
		return "The Lead-only OpenCode plugin delivers actionable Notices as Posse Notice turns through the session API after your current turn ends, without touching the composer. It uses a durable Posse receipt keyed by a stable batch ID and queries the session before retrying. While a prompt runs, it observes at most one successor batch and submits it only after the session is idle. When a replacement session finds a printed receipt from an earlier session, it checks that prior session's history and accepts a recorded receipt or rejects a confirmed absence; unsupported or ambiguous history remains uncertain. Inspect the named session and do not retry blindly; ask the User if the outcome cannot be established. It acknowledges pr_opened without a turn only when lowkey is on; handle and acknowledge all other Notices yourself. Read the current lowkey state and reporting rule in each message. Do not run `posse watch`. " + noPollRule + " End your turn and let that message wake you."
	default:
		return "Notices arrive as a Posse Notice prompt only while your pane is idle and unfocused. Read the current lowkey state and reporting rule in each message. Do not run `posse watch`; run `posse` before you answer the User so waiting Notices are not missed. " + noPollRule + " End your turn and let that prompt wake you."
	}
}

// workerWaitRules tells a Worker how to wait on long commands and PRs.
func workerWaitRules(kind config.Kind) string {
	rules := "\n\nWaiting:\n"
	if kind.BackgroundCommands {
		rules += "- Run long commands (full test suites, e2e, builds) as background commands and never poll them with sleep, ps or repeated reads; do other work or end your turn until they finish.\n"
	}
	rules += "- Never end a turn while a detached command (shell `&`, `nohup`, `setsid`, a polling loop) runs: nothing wakes you when it finishes. Wait in the foreground" + backgroundAlternative(kind) + ".\n"
	return rules + "- Do not wait for PR CI after `posse signal done`; posse watches the PR and the Lead sends fix instructions."
}

func backgroundAlternative(kind config.Kind) string {
	if kind.BackgroundCommands {
		return " or use a background command the harness tracks"
	}
	return ""
}

func noticeDelivery(kind config.Kind) string {
	if kind.NoticeDelivery == "" {
		return config.NoticeDeliveryPrompt
	}
	return kind.NoticeDelivery
}

// leadLaunch is how one Lead agent is started: its arguments and, for kinds
// that cannot receive instructions as a system prompt, the prompt to type once
// it is ready.
type leadLaunch struct {
	Args          []string
	Env           map[string]string
	TypedPrompt   string
	HandoffLoaded bool
	// StartsBusy is true when Args carry the agent's first prompt, so the
	// agent is working as soon as it launches.
	StartsBusy bool
	// OpeningPromptArg is true when the last of Args is that first prompt.
	OpeningPromptArg bool
}

func (s *Service) waitLeadStarted(ctx context.Context, paneID string, launch leadLaunch) error {
	if launch.StartsBusy {
		return s.waitAgentLaunched(ctx, paneID)
	}
	return s.waitAgentReady(ctx, paneID)
}

func (s *Service) prepareLeadLaunch(home string, project store.Project, cfg config.Config, kind string, readiness ...[]readinessGap) (leadLaunch, error) {
	kindConfig := cfg.Kinds[kind]
	var gaps []readinessGap
	if len(readiness) > 0 {
		gaps = readiness[0]
	}
	composed, err := composeLeadInstructionsMode(home, project, cfg, kind, gaps, true)
	if err != nil {
		return leadLaunch{}, err
	}
	instructions := composed.Text
	var skills posseLaunchSkills
	if kind == "claude" || kind == "codex" || kind == "pi" {
		skills, err = freezePosseLaunchSkills(home, project.Name, project.Root, cfg, "lead")
		if err != nil {
			return leadLaunch{}, err
		}
		if kind == "codex" {
			instructions += "\n\n## Posse skills\n\n" + skills.CodexInstructions
		}
	}
	if size := len(instructions); size > leadInstructionMaxBytes {
		message := fmt.Sprintf("Lead instructions exceed the %d-token budget: %d bytes (maximum %d bytes at %d bytes per token)", leadInstructionTokenBudget, size, leadInstructionMaxBytes, leadInstructionBytesPerToken)
		return leadLaunch{}, axi.Failure("lead_instructions_too_large", message, false)
	}
	instructionsFile := filepath.Join(home, "projects", project.Name, "lead.md")
	if err := writeFile(instructionsFile, []byte(instructions)); err != nil {
		return leadLaunch{}, err
	}
	launch := leadLaunch{
		Args:          make([]string, 0, len(kindConfig.AutoApproveArgs)+len(kindConfig.LeadArgs)+len(kindConfig.SystemPromptArgs)+2),
		HandoffLoaded: composed.HandoffLoaded && len(kindConfig.SystemPromptArgs) > 0,
	}
	if kindConfig.LeadAutoApprove {
		launch.Args = append(launch.Args, kindConfig.AutoApproveArgs...)
	}
	launch.Args = append(launch.Args, kindConfig.LeadArgs...)
	text := instructions
	if kind == "codex" {
		// Codex parses -c values as TOML. A JSON string is also a valid TOML
		// basic string, preserving every instruction byte after Codex parses it.
		encoded, err := json.Marshal(instructions)
		if err != nil {
			return leadLaunch{}, err
		}
		text = string(encoded)
	}
	for _, argument := range kindConfig.SystemPromptArgs {
		argument = strings.ReplaceAll(argument, "{file}", instructionsFile)
		launch.Args = append(launch.Args, strings.ReplaceAll(argument, "{text}", text))
	}
	if kind == "claude" {
		plugin, err := s.writeLeadClaudeLowkey(home, project)
		if err != nil {
			return leadLaunch{}, err
		}
		launch.Args = append(launch.Args, "--plugin-dir", plugin, "--plugin-dir", skills.ClaudePluginDir)
		launch.Args, err = appendResearchLaunchArgs(context.Background(), home, project, cfg, kind, launch.Args)
		if err != nil {
			return leadLaunch{}, err
		}
		launch.Args = prependAttributionArgs(kind, cfg.Profiles[cfg.Lead.Profiles[kind]], launch.Args)
		launch.Env = map[string]string{
			"CLAUDE_CODE_ENABLE_FUNCTION_HOOKS": "1",
			"POSSE_LOWKEY_CONFIG":               config.ConfigPath(home, project.Name),
			"POSSE_LOWKEY_GLOBAL_CONFIG":        config.ConfigPath(home, ""),
			"POSSE_LOWKEY_NOTICES_DIR":          claudeNoticeDirectory(home, project.Name),
		}
	}
	if kind == "opencode" && noticeDelivery(kindConfig) == config.NoticeDeliveryOpenCodePlugin {
		plugin, err := s.writeLeadOpenCodePlugin(home, project)
		if err != nil {
			return leadLaunch{}, err
		}
		content, err := openCodePluginConfig(os.Getenv("OPENCODE_CONFIG_CONTENT"), plugin)
		if err != nil {
			return leadLaunch{}, err
		}
		launch.Env = map[string]string{"OPENCODE_CONFIG_CONTENT": content}
	}
	if noticeDelivery(kindConfig) == config.NoticeDeliveryPiExtension {
		extension, err := s.writeLeadPiExtension(home, project)
		if err != nil {
			return leadLaunch{}, err
		}
		launch.Args = append(launch.Args, "--extension", extension)
	}
	if kind == "pi" {
		launch.Args = append(launch.Args, skills.PiArgs...)
	}
	if profileName := cfg.Lead.Profiles[kind]; profileName != "" {
		profile, ok := cfg.Profiles[profileName]
		if !ok {
			return leadLaunch{}, axi.Failure("config_invalid", "Lead Profile "+profileName+" does not exist", false)
		}
		if profile.Kind != kind {
			return leadLaunch{}, axi.Failure("config_invalid", "Lead Profile "+profileName+" kind does not match "+kind, false)
		}
		profileArgs := resolvedProfileArgs(profile, kindConfig)
		if kindConfig.LeadAutoApprove {
			profileArgs = withoutArgumentSequence(profileArgs, kindConfig.AutoApproveArgs)
		}
		launch.Args = append(launch.Args, profileArgs...)
	}
	if kind == "opencode" {
		// --prompt starts a turn without typing into the pane. The first turn
		// creates the session required by the plugin's session API delivery.
